sys_script_include.script:
var GuardianAIAgentHelper = Class.create();
GuardianAIAgentHelper.prototype = {
    initialize: function() {
        this.identity_table_name = "x_aleen_snguardian_identity";
        this.identity_access_table_name = "x_aleen_snguardian_identity_access";
        this.identity_asset_table_name = "x_aleen_snguardian_identity_asset";
        this.visitor_table_name = "x_aleen_snguardian_visitor";
    },
    getIdentityByMail: function(mail) {
        var response = {};
        var identityGr = new GlideRecordSecure(this.identity_table_name);
        identityGr.addQuery('email', mail);
        identityGr.addQuery('is_deleted', false);
        identityGr.query();
        if (identityGr.next()) {
            response['success'] = true;
            var user_type = identityGr.type.code;
            response['full_name'] = identityGr.full_name.toString();
            response['phone'] = identityGr.phone.toString();
            response['sys_id'] = identityGr.sys_id.toString();
            response['email'] = identityGr.email.toString();
            response['type'] = identityGr.type.name.toString();
            if (user_type == 'VISITOR') {
                var visitorGr = new GlideRecordSecure(this.visitor_table_name);
                if (visitorGr.get(identityGr.sys_id)) {
                    response['status'] = visitorGr.visitor_status.name.toString();
                }
            } else {
                response['status'] = identityGr.status.name.toString();
                response['department'] = identityGr.department.toString();
                response['user_name'] = identityGr.user_name.toString();
            }
        } else {
            response['success'] = false;
            response['message'] = "Identity information not found for the supplied email " + mail;
        }
        return response;
    },
    getIdentityAccessByMail: function(mail) {
        var response = {};
        var accessList = [];
        var identity_sys_id = "";
        var identityAccessGr = new GlideRecordSecure(this.identity_access_table_name);
        identityAccessGr.addQuery('identity.email', mail);
        identityAccessGr.addQuery('is_deleted', false);
        identityAccessGr.query();
        while (identityAccessGr.next()) {
            var access = {};
            access['identity_access_identifier'] = identityAccessGr.sys_id.toString();
            access['name'] = identityAccessGr.access_level.name.toString();
            access['valid_from'] = identityAccessGr.valid_from.toString();
            access['valid_to'] = identityAccessGr.valid_to.toString();
            accessList.push(access);
            if (identity_sys_id == "") {
                identity_sys_id = identityAccessGr.identity.toString();
            }
        }
        if (accessList.length > 0) {
            response['GUADIAN_USER_FOUND'] = true;
            response['GUADIAN_USER_HAS_ACCESS'] = true;
            response['ACCESS_LIST'] = accessList;
        } else {
            var userResponse = this.getIdentityByMail(mail);
            if (userResponse['success']) {
                response['GUADIAN_USER_FOUND'] = true;
                response['GUADIAN_USER_HAS_ACCESS'] = false;
                response['ACCESS_LIST'] = [];
                identity_sys_id = userResponse['sys_id'];
            } else {
                response['GUADIAN_USER_FOUND'] = false;
                response['GUADIAN_USER_HAS_ACCESS'] = false;
                response['ACCESS_LIST'] = [];
            }
        }
        response['GUARDIAN_USER_IDENTIFIER'] = identity_sys_id;
        return response;
    },
    getIdentityAssetsByMail: function(mail) {
        var response = {};
        var assetsList = [];
        var identity_sys_id = "";
        var identityAssetGr = new GlideRecordSecure(this.identity_asset_table_name);
        identityAssetGr.addQuery('identity.email', mail);
        identityAssetGr.addQuery('is_deleted', false);
        identityAssetGr.query();
        while (identityAssetGr.next()) {
            var asset = {};
            asset['identity_asset_identifier'] = identityAssetGr.sys_id.toString();
            asset['badge_id'] = identityAssetGr.asset.serial.toString();
            asset['badge_type'] = identityAssetGr.asset.type.name.toString();
            asset['valid_from'] = identityAssetGr.valid_from.toString();
            asset['valid_to'] = identityAssetGr.valid_to.toString();
            asset['status'] = identityAssetGr.status.name.toString();
            assetsList.push(asset);
            if (identity_sys_id == "") {
                identity_sys_id = identityAssetGr.identity.toString();
            }
        }
        if (assetsList.length > 0) {
            response['GUADIAN_USER_FOUND'] = true;
            response['GUADIAN_USER_HAS_ASSETS'] = true;
            response['ASSETS_LIST'] = assetsList;
        } else {
            var userResponse = this.getIdentityByMail(mail);
            if (userResponse['success']) {
                response['GUADIAN_USER_FOUND'] = true;
                response['GUADIAN_USER_HAS_ASSETS'] = false;
                response['ASSETS_LIST'] = [];
                identity_sys_id = userResponse['sys_id'];
            } else {
                response['GUADIAN_USER_FOUND'] = false;
                response['GUADIAN_USER_HAS_ASSETS'] = false;
                response['ASSETS_LIST'] = [];
            }
        }
        response['GUARDIAN_USER_IDENTIFIER'] = identity_sys_id;
        return response;
    },
    getIdentityAssetsByMailandSerial: function(mail, serial) {
        var response = [];
        var identityAssetGr = new GlideRecordSecure(this.identity_asset_table_name);
        identityAssetGr.addQuery('identity.email', mail);
        identityAssetGr.addQuery('asset.serial', serial);
        identityAssetGr.addQuery('is_deleted', false);
        identityAssetGr.query();
        while (identityAssetGr.next()) {
            var asset = {};
            asset['badge_id'] = identityAssetGr.asset.serial.toString();
            asset['badge_type'] = identityAssetGr.asset.type.name.toString();
            asset['valid_from'] = identityAssetGr.valid_from.toString();
            asset['valid_to'] = identityAssetGr.valid_to.toString();
            asset['status'] = identityAssetGr.status.name.toString();
            asset['identity_asset_sys_id'] = identityAssetGr.toString();
            asset['asset_sys_id'] = identityAssetGr.asset.toString();
            response.push(asset);
        }
        return response;
    },
    getDTConfigs(decision_table_sysid, input_object) {
        var dtInputs = {};
        // Create separate object for DT inputs
        if (input_object.user_location) {
            var locationGr = new GlideRecordSecure('x_aleen_snguardian_location');
            locationGr.addQuery('sys_id', input_object.user_location);
            locationGr.query();
            if (locationGr.next()) {
                dtInputs['u_location'] = locationGr;
            }
        }
        if (input_object.user_type) {
            var identityType = new GlideRecordSecure('x_aleen_snguardian_identitytype');
            identityType.addQuery('sys_id', input_object.user_type);
            identityType.query();
            if (identityType.next()) {
                dtInputs['u_type'] = identityType;
            }
        }
        if (input_object.badge_type) {
            dtInputs['u_badge_type'] = input_object.badge_type;
        }
        if (input_object.badge_action) {
            dtInputs['u_badge_action'] = input_object.badge_action;
        }
        var dt = new sn_dt.DecisionTableAPI();
        var result = {};
        try {
            var response = dt.getDecisions(decision_table_sysid, dtInputs);
            var output = [];

            for (var kl = 0; kl < response.length; kl++) {
                var decision = response[kl];
                var elements = decision['result_elements'];
                var formattedDecision = {};

                for (var key in elements) {
                    if (elements[key] != null) {
                        var newKey = key.startsWith("u_") ? key.slice(2) : key;
                        newKey = newKey.replace(/([a-z])/g, function(letter) {
                            return letter;
                        });
                        formattedDecision[newKey] = elements[key].getValue();
                    }
                }
                output.push(formattedDecision);
            }

            if (output.length > 0) {
                result = output[0];
                gs.info("returning first record " + JSON.stringify(output[0]));
            } else {
                result = {};
            }
        } catch (e) {
            gs.error("Error in getting decisions from the Decision Table: " + e.message);
            result = {};
            return result;
        }
        return result;
    },
    type: 'GuardianAIAgentHelper'
};
